ported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","type":"no_verified_cover_asset_retained","isbn13":"9789028427792","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":14860006,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:26:38.922Z","editionKey":"/books/OL42068804M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987246036,"bound_title":"Orkaanseizoen","reviewed_at":"2026-11-03T09:26:38.922+00:00","bound_isbn13":"9789028427792","evidence_url":"https://data.bibliotheken.nl/id/nbt/p424305720","review_batch":"nl-scale-20261102-047","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987346016}'::jsonb as exact union all select 'catalog_work_descriptions:67' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987146038 and t.language='nl')='{"text":"Arts Marc Seidman overleeft een schietpartij in zijn huis. Wanneer hij in het ziekenhuis bijkomt, hoort hij dat zijn vrouw is omgekomen en hun babydochter verdwenen is. Een losgeldeis biedt hoop, maar de overdracht loopt mis. Na een lange periode zonder nieuws krijgt Marc opnieuw een bericht met aanwijzingen dat zijn dochter nog leeft. Hij moet bepalen wat hij met die nieuwe mogelijkheid doet. De zoektocht plaatst zijn wanhoop en behoefte aan zekerheid tegenover mensen van wie de bedoelingen onduidelijk blijven.","work_id":987146038,"evidence":[{"note":"Retain existing Work3519 No second chance / Harlan Coben and exact Dutch Geen tweede kans 9789022562390 Paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-026.json retained. No abr